function COUNT_PATTERNS(widths = [w_1, ..., w_L]):
    product_form <- 1
    for w in widths:
        product_form <- product_form * 2^w
    sum_form <- 2 ^ (sum of widths)
    assert product_form == sum_form
    return product_form

function ENUMERATE_PATTERNS(widths):
    layer_choices <- for each w: all Boolean tuples of length w
    return Cartesian product of layer_choices

function CERTIFY_BOUND(d2, d1, cells, widths):
    (dim_C1, rank_Z, rank_B, beta) <- BETTI(d2, d1)
    n_cells <- cells                       # observed number of 1-cells
    ap_count <- 2 ^ (sum of widths)
    step1 <- (beta <= n_cells)             # topology: subquotient bound
    step2 <- (n_cells <= ap_count)         # geometry: cells <= patterns
    certified <- step1 AND step2
    return { beta, n_cells, ap_count,
             step1, step2, certified }
